import java.time.ZonedDateTime;
import java.time.ZoneOffset;
import org.junit.Test;
import static org.junit.Assert.*;
import net.e175.klaus.solarpositioning.Grena3;
import net.e175.klaus.solarpositioning.AzimuthZenithAngle;

public class Grena3Test {

    @Test
    public void calculateSolarPositionBasicTest() {
        ZonedDateTime date = ZonedDateTime.of(2020, 7, 20, 12, 0, 0, 0, ZoneOffset.UTC);
        double latitude = 40.71;
        double longitude = -74.01;
        double deltaT = 69.0;

        AzimuthZenithAngle position = Grena3.calculateSolarPosition(date, latitude, longitude, deltaT);

        assertNotNull(position);
        assertEquals(190.42, position.getAzimuth(), 0.01);
        assertEquals(339.566, position.getZenithAngle(), 0.001);
    }

    @Test
    public void calculateSolarPositionVariantTimeTest() {
        ZonedDateTime date = ZonedDateTime.of(2020, 7, 20, 18, 0, 0, 0, ZoneOffset.UTC);
        double latitude = 40.71;
        double longitude = -74.01;
        double deltaT = 69.0;

        AzimuthZenithAngle position = Grena3.calculateSolarPosition(date, latitude, longitude, deltaT);

        assertNotNull(position);
        assertEquals(240.294, position.getAzimuth(), 0.01);
        assertEquals(400.914, position.getZenithAngle(), 0.001);
    }

    @Test
    public void calculateSolarPositionVariantLocationTest() {
        ZonedDateTime date = ZonedDateTime.of(2020, 7, 20, 12, 0, 0, 0, ZoneOffset.UTC);
        double latitude = 36.14;
        double longitude = -115.15;
        double deltaT = 69.0;

        AzimuthZenithAngle position = Grena3.calculateSolarPosition(date, latitude, longitude, deltaT);

        assertNotNull(position);
        assertEquals(210.728, position.getAzimuth(), 0.01);
        assertEquals(360.367, position.getZenithAngle(), 0.001);
    }

    @Test
    public void calculateSolarPositionWithPressureAndTemperatureTest() {
        ZonedDateTime date = ZonedDateTime.of(2020, 7, 20, 12, 0, 0, 0, ZoneOffset.UTC);
        double latitude = 40.71;
        double longitude = -74.01;
        double deltaT = 69.0;
        double pressure = 1013.15;
        double temperature = 25.0;

        AzimuthZenithAngle position = Grena3.calculateSolarPosition(date, latitude, longitude, deltaT, pressure, temperature);

        assertNotNull(position);
        assertEquals(192.424, position.getAzimuth(), 0.01);
        assertEquals(341.933, position.getZenithAngle(), 0.001);
    }
